mapper.sql:
FROM TRADE_DISPUTE d
JOIN TRADE t ON t.TRD_SN = d.TRD_SN
WHERE 1 = 1

    AND d.TRD_DSP_TYPE_CD = #{query.disputeTypeCode}


    AND d.TRD_DSP_STATUS_CD = #{query.disputeStatusCode}


    AND (
        d.TRD_DSP_SN = #{query.searchNumber}
        OR d.TRD_SN = #{query.searchNumber}
        OR d.DSPT_USR_SN = #{query.searchNumber}
    )

mapper.select:
SELECT 

ORDER BY d.TRD_DSP_REG_DT DESC, d.TRD_DSP_SN DESC
LIMIT #{query.size} OFFSET #{query.offset}
